def expand_to_800():
    with SessionLocal() as db:
        categories = {c.name: c for c in db.scalars(select(Category)).all()}
        missing = [name for name in NAMES if name not in categories]
        if missing:
            raise SystemExit("Missing categories: " + ", ".join(missing) + ". Start the app once first, then rerun.")
        added = 0
        for category_name, names in NAMES.items():
            category = categories[category_name]
            current = db.scalar(select(func.count(Product.id)).where(Product.category_id == category.id)) or 0
            existing_titles = set(db.scalars(select(Product.title).where(Product.category_id == category.id)).all())
            existing_skus = set(db.scalars(select(Product.sku)).all())
            for name in names:
                if current >= 100:
                    break
                if name in existing_titles:
                    continue
                sku = f"PJ-{category_name[:3].upper()}-{current+1:03d}"
                suffix = 1
                while sku in existing_skus:
                    suffix += 1
                    sku = f"PJ-{category_name[:3].upper()}-{current+1:03d}-{suffix}"
                image_file = f"photo-{category_name.lower()}.jpg"
                description = (
                    f"{name}, from the PJ jewellery catalogue. This catalogue entry is a design reference "
                    f"with a category-specific studio photograph. Confirm metal, purity, gemstone details, "
                    f"weight and dimensions with the supplier before publishing as factual product specifications."
                )
                db.add(Product(
                    sku=sku, title=name, description=description,
                    category_id=category.id, tags=TAGS[category_name],
                    image_path=image_file, status="published", archived=False
                ))
                existing_titles.add(name); existing_skus.add(sku)
                current += 1; added += 1
        db.commit()
        print(f"Added {added} products.")
        print("Category totals:")
        for name, category in categories.items():
            count = db.scalar(select(func.count(Product.id)).where(Product.category_id == category.id)) or 0
            print(f"  {name}: {count}")
def main():
    expand_to_800()

if __name__ == "__main__":
    main()
